mapper.select:
select count(bp.patient_id)
from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id

    bp.origin_type_name is not null
    and bp.origin_type is not null

select
bp.origin_type originType,
bp.origin_type_name originTypeName,
count(bp.origin_type) countType,
concat( format(count(bp.origin_type) / ${countOriginType} * 100, 2 ),'%') percentage
from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id

    bp.origin_type_name is not null
    and bp.origin_type is not null

group by bp.origin_type

select count(bp.gender)
from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id

    bp.gender is not null

select
case when bp.gender = 0 then '男'
when bp.gender = 1 then '女'
else '未知'
end gender,
count(bp.gender) countGender,
concat( format(count(bp.gender) / ${countGender} * 100, 2 ),'%') percentage
from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id

    bp.gender is not null

group by bp.gender

select count(1) from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id

select count(1) from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id

    bp.birthday is not null

        AND TIMESTAMPDIFF(YEAR, DATE_FORMAT(bp.birthday,'%Y-%m-%d'), CURDATE()) <= #{ageOne}



        AND TIMESTAMPDIFF(YEAR, DATE_FORMAT(bp.birthday,'%Y-%m-%d'), CURDATE()) > #{ageTwo}



        AND TIMESTAMPDIFF(YEAR, DATE_FORMAT(bp.birthday,'%Y-%m-%d'), CURDATE()) <= #{ageThree}

select bp.patient_id, bp.name, bp.mobile, btp.treatmentId, btp.lastVisitDate, btp.dentistId, btp.employeeName, btp.treatType from ( select btp.patientId, btp.treatmentId, date_format(btp2.treat_end_time, '%Y-%m-%d') as lastVisitDate, btp2.registered_dentist_id as dentistId, be.employee_name as employeeName, btp2.treat_type as treatType from ( select btp.patient_id as patientId, max(btp.treatment_id) AS treatmentId from base_treatment_process btp
and btp.org_id = #{form.orgId}
and btp.treat_end_time is not null
group by btp.patient_id ) btp inner join base_treatment_process btp2 on btp.treatmentId = btp2.treatment_id left join base_employee be on btp2.registered_dentist_id = be.user_id
and date_format(btp2.treat_end_time, '%Y-%m-%d') >= #{form.startDate}
and date_format(btp2.treat_end_time, '%Y-%m-%d') <= #{form.endDate}
and btp2.registered_dentist_id in
#{item}
and btp2.treat_type in
#{item}
) btp left join ( select bp.patient_id, bp.name, bp.mobile, ifnull(btp1.appointCount, 0) as appointCount, ifnull(bvr.visitCount, 0) as visitCount from base_patient bp LEFT JOIN ( SELECT patient_id, count(btp.patient_id) AS appointCount FROM base_treatment_process btp WHERE DATE_FORMAT(btp.appoint_start_time, '%Y-%m-%d') > current_date GROUP BY patient_id ) btp1 ON bp.patient_id = btp1.patient_id LEFT JOIN ( SELECT patient_id, count(bvr.patient_id) AS visitCount FROM base_visit_remind bvr WHERE bvr.type = 1 AND DATE_FORMAT(bvr.time, '%Y-%m-%d') > current_date GROUP BY patient_id ) bvr ON bp.patient_id = bvr.patient_id
and concat(IFNULL(bp.`name`,''),IFNULL(bp.pinyin_name,''),IFNULL(bp.mobile,'')) like concat(concat('%',#{form.combination}),'%')
) bp on btp.patientId = bp.patient_id where bp.appointCount = 0 and bp.visitCount = 0

SELECT
DISTINCT btp.patient_id AS patientId
FROM base_treatment_process btp

    btp.treat_status IN (3, 4)
    AND btp.treat_type = 0


            AND DATE_FORMAT(btp.treat_start_time,'%Y-%m-%d') between DATE_FORMAT(#{query.startDate},'%Y-%m-%d')
            and DATE_FORMAT(#{query.endDate},'%Y-%m-%d')




            AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') between #{query.startDate}
            and #{query.endDate}




            AND DATE_FORMAT(btp.treat_start_time,'%Y') between #{query.startDate}
            and #{query.endDate}

SELECT bp.origin_type AS originType, bp.org_id AS orgId, count(bp.patient_id) firstVisitCount FROM base_patient bp
AND bp.origin_type in
#{item}
AND bp.patient_id in
#{item}
GROUP BY bp.origin_type, bp.org_id

select count(1) from base_patient bp inner join (
select distinct btp.patient_id
from base_treatment_process btp

    and btp.treat_status > 1

        AND btp.org_id = #{form.orgId}


        AND cast(btp.treat_start_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(btp.treat_start_time,'%Y-%m') = #{form.monthDay}
        and DATE_FORMAT(btp.treat_end_time, '%Y-%m') = #{form.monthDay}



        AND year(btp.treat_start_time) =#{form.year}
        AND year(btp.treat_end_time) =#{form.year}


) bp1 on bp1.patient_id = bp.patient_id
where bp.birthday is null

SELECT bp.patient_id AS patientId, name FROM base_patient bp
AND bp.patient_id in
#{item}

select bp.patient_id, bp.`name` as patientName, bp.medical_number as medicalNumber, timestampdiff(year, bp.birthday, curdate()) as age, case when bp.gender = 0 then '男' when bp.gender = 1 then '女' else '未知' end as gender, bp.mobile, bp.vip_logo as patientType, pm.cumulative_consumption as totalConsumeAmount, pm.total_arrears as totalOweAmount, pm.member_level_name as memberTypeName, pm.member_balance as memberBalance, pm.principal_balance as principalBalance, bp.origin_id, bp.origin_type_name as patientOrionTypeName, bpo.name as patientOrionName, date_format(bp.first_visit_date, '%Y/%m/%d')as firstVisitDate, bo.abbreviation as firstVisitOutpatient, be.employee_name as firstVisitDoctors, date_format(bp.last_visit_date, '%Y/%m/%d') as lastVisitDate, be1.employee_name as lastVisitDoctors, pm.number_of_visits as treatQuantity from base_patient bp left join base_employee be on be.user_id = bp.first_visit_doctors left join base_employee be1 on be1.user_id = bp.last_visit_doctors left join base_patient_origin bpo on bpo.id = bp.origin_id left join base_organization bo on bo.org_id = bp.first_visit_outpatient left join patient_manage pm on bp.patient_id = pm.patient_id
(bp.name like concat('%', #{query.patientKeyWord}, '%') or bp.mobile like concat('%', #{query.patientKeyWord}, '%') or bp.medical_number like concat('%', #{query.patientKeyWord}, '%') or bp.pinyin_name like concat('%', #{query.patientKeyWord}, '%'))
and date_format(bp.birthday, '%Y') >= #{startAge} and date_format(bp.birthday, '%Y') <= #{endAge}
and bp.vip_logo = #{query.patientType}
and pm.member_level_id = #{query.memberType}
and bp.gender = #{query.gender}
and bp.first_visit_outpatient = #{query.firstOrgId}
and be.employee_name like concat('%', #{query.firstDentistName}, '%')
and be1.employee_name like concat('%', #{query.lastDentistName}, '%')
and pm.total_arrears >= #{query.startOweAmount} and pm.total_arrears <= #{query.endOweAmount}
and pm.principal_balance >= #{query.startPrincipalBalance} and pm.principal_balance <= #{query.endPrincipalBalance}
and pm.member_balance >= #{query.startMemberBalance} and pm.member_balance <= #{query.endMemberBalance}
and pm.cumulative_consumption >= #{query.startConsumeAmount} and pm.cumulative_consumption <= #{query.endConsumeAmount}
and pm.number_of_visits >= #{query.startTreatQuantity} and pm.number_of_visits <= #{query.endTreatQuantity}

SELECT p.patient_id , p.name as 'patientName' , p.mobile , p.gender , TimeStampDiff(YEAR, p.birthday, now()) as 'age' , p.medical_number , lo.abbreviation , p.vip_logo , ifnull(p.visit_rate, 0) as 'visit_rate' , ifnull(p.cumulative_consumption, 0) as 'cumulative_consumption' , p.vip_score , date_format(p.last_visit_date, '%Y-%m-%d') as 'last_visit_date' , ifnull(t.appoint_start_time, '') as 'nextAppointTime' , ifnull(v.remind_time, '') as 'nextRemindTime' , m.member_level_name , c.coupon_name , p.vip_logo_old FROM base_patient p left join ( select m.patient_id, m.member_level_name, m.member_level_id from base_patient_member m where m.type = 0 and m.member_level_id < 4 ) m on p.patient_id = m.patient_id left join ( select c.patient_id, max(g.coupon_name) as 'coupon_name' from base_card c left join base_coupon g on c.coupon_id = g.coupon_id where c.status > 1 and (g.coupon_name like '%365%' or g.product_type_name in ('青藤', '银藤', '金藤')) group by c.patient_id ) c on p.patient_id = c.patient_id left join base_organization lo on p.last_visit_outpatient = lo.org_id left join ( select t.patient_id, date_format(min(t.appoint_start_time), '%Y-%m-%d') as 'appoint_start_time' from base_treatment_process t where t.appointment_id is not null and t.treatment_id is null and t.appoint_start_time >= date_add(date_format(now(), '%Y-%m-%d'), INTERVAL 1 DAY) group by t.patient_id ) t on p.patient_id = t.patient_id left join ( select v.patient_id, date_format(min(v.time), '%Y-%m-%d') as 'remind_time' from base_visit_remind v where v.type = 1 and v.time >= date_add(date_format(now(), '%Y-%m-%d'), INTERVAL 1 DAY) group by v.patient_id ) v on p.patient_id = v.patient_id
p.vip_logo is not null
and concat(ifnull(p.name, ''), ifnull(p.pinyin_name, ''), ifnull(p.mobile, '')) like concat('%', #{form.combination}, '%')
and p.last_visit_outpatient in
#{item}
and p.vip_logo in
#{item}
and p.vip_logo_old in
#{item}
and m.member_level_id in
#{item}
